/**
 * 200 synthetic tools (40 resources × 5 operations) with Portuguese descriptions in the style
 * of the ones generated by the crawler (domain fixture), and an evaluation set of natural-language
 * queries (F7.1). Descriptions carry no read-only/destructive suffix: the gateway appends a
 * localized one at `tools/list` time (ADR-012).
 */

export interface SyntheticTool {
  name: string;
  title: string;
  description: string;
  inputSchema: Record<string, unknown>;
  annotations: Record<string, boolean>;
  tags: string[];
}

interface Resource {
  source: string;
  key: string;
  singular: string;
  plural: string;
  /** Phrase describing the resource (goes into the descriptions). */
  about: string;
  filters: string[];
  fields: string[];
}

const R = (source: string, key: string, singular: string, plural: string, about: string, filters: string[], fields: string[]): Resource => ({
  source,
  key,
  singular,
  plural,
  about,
  filters,
  fields,
});

