const OPS = [
  { verb: 'list', title: (r: Resource) => `Lista ${r.plural}`, desc: (r: Resource) => `Lista ${r.plural} com filtros e paginação. Consulta de ${r.about}.`, ann: { readOnlyHint: true } },
  { verb: 'get', title: (r: Resource) => `Busca ${r.singular}`, desc: (r: Resource) => `Busca os detalhes de um ${r.singular} pelo identificador. Consulta de ${r.about}.`, ann: { readOnlyHint: true } },
  { verb: 'create', title: (r: Resource) => `Cadastra ${r.singular}`, desc: (r: Resource) => `Cadastra um novo registro de ${r.singular}. Inclusão em ${r.about}.`, ann: { readOnlyHint: false } },
  { verb: 'update', title: (r: Resource) => `Atualiza ${r.singular}`, desc: (r: Resource) => `Atualiza os dados de um ${r.singular} existente. Alteração em ${r.about}.`, ann: { readOnlyHint: false, idempotentHint: true } },
  { verb: 'delete', title: (r: Resource) => `Remove ${r.singular}`, desc: (r: Resource) => `Remove (exclui) um ${r.singular}. Exclusão em ${r.about}.`, ann: { readOnlyHint: false, destructiveHint: true } },
] as const;

export function syntheticTools(): SyntheticTool[] {
  const out: SyntheticTool[] = [];
  for (const r of SYNTHETIC_RESOURCES) {
    for (const op of OPS) {
      const props: Record<string, unknown> = {};
      if (op.verb === 'list') for (const f of r.filters) props[f] = { type: 'string' };
      if (op.verb !== 'list' && op.verb !== 'create') props.id = { type: 'string' };
      if (op.verb === 'create' || op.verb === 'update') for (const f of r.fields) props[f] = { type: 'string' };
      out.push({
        name: `${r.source}_${r.key}_${op.verb}`,
        title: op.title(r),
        // Simulates the indexed text of a generated tool: `buildSearchText` appends this Portuguese effect
        // sentence for openapi tools (ADR-009/ADR-012). These fixtures are inserted as `manual`, so it lives here.
        description: `${op.desc(r)} ${op.ann.readOnlyHint ? 'Somente leitura.' : 'Altera dados.'}`,
        inputSchema: { type: 'object', properties: props, ...(props.id ? { required: ['id'] } : {}) },
        annotations: op.ann,
        tags: [r.source, r.key],
      });
    }
  }
  return out;
}

