/**
 * Deterministic embedder for tests (hashing of normalized words into 256 dimensions).
 * It has no real semantics, but exercises the vector path and the ranking fusion.
 */
export function hashingEmbedder(dimensions = 256): { name: string; embed(texts: string[]): Promise<number[][]> } {
  const norm = (w: string) => w.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
  return {
    name: 'hashing-test',
    async embed(texts) {
      return texts.map((t) => {
        const v = new Array<number>(dimensions).fill(0);
        for (const raw of t.split(/[^\p{L}\p{N}]+/u)) {
          const w = norm(raw).slice(0, 5); // prefix ~ crude stem
          if (w.length < 3) continue;
          let h = 2166136261;
          for (const ch of w) h = Math.imul(h ^ ch.charCodeAt(0), 16777619);
          v[Math.abs(h) % dimensions]! += 1;
        }
        const len = Math.hypot(...v) || 1;
        return v.map((x) => x / len);
      });
    },
  };
}
